const responseTemplates = [
  [/^User created successfully for (.+)\.$/, "User created successfully for {email}.", ["email"]],
  [/^User updated successfully for (.+)\.$/, "User updated successfully for {email}.", ["email"]],
  [/^Password reset completed for (.+)\.$/, "Password reset completed for {email}.", ["email"]],
  [/^User deleted successfully for (.+)\.$/, "User deleted successfully for {email}.", ["email"]],
  [/^Stock record deleted for (.+)\.$/, "Stock record deleted for {symbol}.", ["symbol"]],
  [/^Imported (\d+) historical price rows for (.+)\.$/, "Imported {count} historical price rows for {company}.", ["count", "company"]],
];

export function translate(text, language = "en", values = {}) {
  if (typeof text !== "string") return text;
  let key = text.replace(/\s+/g, " ").trim();
  if (!Object.hasOwn(messages, key)) {
    for (const [pattern, template, fields] of responseTemplates) {
      const match = key.match(pattern);
      if (!match) continue;
      key = template;
      values = { ...Object.fromEntries(fields.map((field, index) => [field, match[index + 1]])), ...values };
      break;
    }
  }
  const index = language === "si" ? 0 : language === "ta" ? 1 : -1;
  const result = (index >= 0 ? messages[key]?.[index] : undefined) || text;
  return result.replace(/\{(\w+)\}/g, (match, name) => Object.hasOwn(values, name) ? String(values[name]) : match);
}
